package ics.recents;

import android.content.res.Resources;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Color;
import android.graphics.Rect;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.graphics.drawable.NinePatchDrawable;
import android.util.Base64;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.HashMap;

/** TechnoUI's real volume panel artwork (gbvol_*), embedded. 9-patch borders are kept and parsed at runtime. */
public class VolArt {
    static final HashMap<String, String> B64 = new HashMap<String, String>();
    static final HashMap<String, Integer> DPI = new HashMap<String, Integer>();
    static final HashMap<String, Bitmap> CACHE = new HashMap<String, Bitmap>();

    static void put(String k, int dpi, String b64) { B64.put(k, b64); DPI.put(k, dpi); }

    static {
        put("dialog", 320, "");
        put("track", 320, "iVBORw0KGgoAAAANSUhEUgAAABYAAAAaCAYAAACzdqxAAAAAAXNSR0IArs4c6QAAAARzQklUCAgICHwIZIgAAABXSURBVEiJ7daxCcAwDETRr5DBMo5G0rRKCpMiqXUGgf4ArzgEtrG6+WYU9EdLzEOAAtAPVjUbd4ZPAHe/KtGIWHBmlsLK5o4H3g0r3rymU0h6PybVO9sD6XENprPg5+sAAAAASUVORK5CYII=");
        put("primary", 320, "iVBORw0KGgoAAAANSUhEUgAAABYAAAAaCAYAAACzdqxAAAAAAXNSR0IArs4c6QAAAARzQklUCAgICHwIZIgAAABTSURBVEiJY2SAgP8MqICRgQoA3VCqmMlEA0MZGBgYGIaewbQCo2GMAIwMDAwMxlufUjUtn/WWHoJBMWowzcFozhvqBtOizhuiQUETAGuYUDucGQFSbAsmdMrdngAAAABJRU5ErkJggg==");
        put("thumb", 320, "");
        put("thumb_pressed", 320, "");
        put("vol", 320, "");
        put("vol_mute", 320, "");
        put("ring", 320, "");
        put("ring_vib", 320, "");
        put("ring_mute", 320, "");
        put("alarm", 320, "");
        put("alarm_mute", 320, "");
        put("phone", 320, "");
        put("more", 240, "");
    }

    static synchronized Bitmap bmp(String k) {
        Bitmap b = CACHE.get(k);
        if (b == null) {
            byte[] raw = Base64.decode(B64.get(k), Base64.DEFAULT);
            BitmapFactory.Options o = new BitmapFactory.Options();
            o.inScaled = false;
            b = BitmapFactory.decodeByteArray(raw, 0, raw.length, o);
            b.setDensity(DPI.get(k));
            CACHE.put(k, b);
        }
        return b;
    }

    /** plain PNG, scaled by its source density like a normal resource */
    static Drawable get(Resources res, String k) {
        return new BitmapDrawable(res, bmp(k));
    }

    // ---- 9-patch (apktool keeps the 1px marker border; rebuild the chunk) ----
    static boolean black(int p) {
        return Color.alpha(p) > 128 && Color.red(p) < 64 && Color.green(p) < 64 && Color.blue(p) < 64;
    }

    /** runs of black marker pixels along one border, in content coordinates: [start0,end0,start1,end1...] */
    static int[] runs(Bitmap s, boolean horizontal, int fixed) {
        int n = (horizontal ? s.getWidth() : s.getHeight()) - 2;
        java.util.ArrayList<Integer> r = new java.util.ArrayList<Integer>();
        int start = -1;
        for (int i = 0; i <= n; i++) {
            boolean on = i < n && black(horizontal ? s.getPixel(i + 1, fixed) : s.getPixel(fixed, i + 1));
            if (on && start < 0) start = i;
            if (!on && start >= 0) { r.add(start); r.add(i); start = -1; }
        }
        int[] out = new int[r.size()];
        for (int i = 0; i < out.length; i++) out[i] = r.get(i);
        return out;
    }

    static Drawable nine(Resources res, String k) {
        Bitmap src = bmp(k);
        int w = src.getWidth(), h = src.getHeight();
        int[] xr = runs(src, true, 0), yr = runs(src, false, 0);
        int[] pr = runs(src, false, w - 1), pb = runs(src, true, h - 1);
        int cw = w - 2, ch = h - 2;
        int padL = pb.length >= 2 ? pb[0] : 0, padR = pb.length >= 2 ? cw - pb[pb.length - 1] : 0;
        int padT = pr.length >= 2 ? pr[0] : 0, padB = pr.length >= 2 ? ch - pr[pr.length - 1] : 0;
        if (xr.length == 0) xr = new int[]{0, cw};
        if (yr.length == 0) yr = new int[]{0, ch};
        int colors = (xr.length + 1) * (yr.length + 1);
        ByteBuffer bb = ByteBuffer.allocate(32 + (xr.length + yr.length + colors) * 4).order(ByteOrder.nativeOrder());
        bb.put((byte) 1).put((byte) xr.length).put((byte) yr.length).put((byte) colors);
        bb.putInt(0).putInt(0);
        bb.putInt(padL).putInt(padR).putInt(padT).putInt(padB);
        bb.putInt(0);
        for (int v : xr) bb.putInt(v);
        for (int v : yr) bb.putInt(v);
        for (int i = 0; i < colors; i++) bb.putInt(1); // NO_COLOR
        Bitmap content = Bitmap.createBitmap(src, 1, 1, cw, ch);
        content.setDensity(src.getDensity());
        return new NinePatchDrawable(res, content, bb.array(), new Rect(padL, padT, padR, padB), k);
    }
}
